function cdqOuvrirPdfCommeSheetV2275(id){
  if(navigator.onLine===false){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  cdqMarquerPdfOuvertV2275(id);

  // V23.14 : le PDF repasse par le moteur PDF propre à Balance CDQ.
  // Il est chargé par le backend/Drive déjà connecté de l'application,
  // puis le lecteur configuré (CDQ / iLovePDF / Acrobat) est proposé.
  // Aucun compte Google Android supplémentaire n'est nécessaire ici.
  return cdqOpenPdf(id).catch(afficherErreur);
}
